public static SysColorHex color2hex(OLE_Color _color, boolean _switchBlueRed = false)
{
    SysColorHex  retColor;
    System.Drawing.Color	color =  System.Drawing.ColorTranslator::FromWin32(_color);
    int						Red = color.R;
    int						Green = color.G;
    int						Blue = color.B;
    int						colorInt = (_switchBlueRed ? Red : Blue) + Green << 8  + (_switchBlueRed ? Blue : Red) << 16;

    retColor = int2Hex(colorInt);
    return strRFix(retColor, 6, '0'); // make sure that it will return 6 chars even when having 00FF00 that earlier just produced FF00.
}

public static int scaleColor(int _color, real _scalar)
{
    System.Drawing.Color color =  System.Drawing.Color::FromArgb(_color);
    real red	= color.R;
    real green	= color.G;
    real blue	= color.B;
    color = System.Drawing.Color::FromArgb(255, real2int(red * _scalar), real2int(green * _scalar), real2int(blue * _scalar));
    return color.ToArgb();
}

public static OLE_Color hex2color(SysColorHex _color)
{
    System.Drawing.Color color =  System.Drawing.Color::FromArgb(hex2Int(_color));
    return System.Drawing.ColorTranslator::ToOle(color);
}

public static System.Drawing.Bitmap addBackgroundColor(System.Drawing.Bitmap _image, int _backRed = 255, int _backGreen= 255, int _backBlue = 255, int _backAlpha = 255)
{
    int i, j;
    System.Drawing.Bitmap bmp = new System.Drawing.Bitmap(_image.Width,_image.Height);
    System.Drawing.Graphics g = System.Drawing.Graphics::FromImage(bmp);
    g.DrawRectangle(new System.Drawing.Pen(new System.Drawing.SolidBrush(System.Drawing.Color::FromArgb(_backAlpha, _backRed, _backGreen, _backBlue))), 0, 0, _image.Width, _image.Height);
    /*for (i = 0; i <_image.Width; i++)
    {
        for (j= 0; j < _image.Height; j++)
        {
            bmp.SetPixel(i,j,System.Drawing.Color::FromArgb(_backAlpha, _backRed, _backGreen, _backBlue));
        }
    }*/

    g.DrawImage(_image,0,0,_image.Width,_image.Height);
    return bmp;
}

