        //rect = new System.Drawing.Rectangle(2 ,2 ,image.Height - 10 , image.Height - 10);
        //graphics.DrawImage(image, rect);

        //TFMGraphicsHelper::drawGradient(graphics, image.Height ,30,image.Width * 2 - image.Height -1,image.Height*2 - 60,235 + 235 << 8 + 235 << 16 + 255 << 24, 212 + 212 << 8 + 212 << 16 + 255 << 24,false,false);

        //TFMGraphicsHelper::drawBmpEdges(graphics, image.Height+1 ,31,image.Width * 2 - image.Height -3,image.Height*2 - 62, 255 << 24,false,false);
        //TFMGraphicsHelper::drawBmpEdges(graphics, image.Height ,30,image.Width * 2 - image.Height -1,image.Height*2 - 60, 255 << 24,false,false);

        rect = new System.Drawing.Rectangle(0 ,0 ,image.Height*2 , image.Height*2);
