/// <summary>
/// Dampens an RGB integer by a scale
/// </summary>
/// <param name="_rgbInt">
/// The RGB integer to dampen.
/// </param>
/// <param name="_scale">
/// The scale by which to dampen the colors in the integer.
/// </param>
/// <returns>
/// The resulting RGB value.
/// </returns>
public static int dampenRGB(int _rgbInt, real _scale)
{
    int r,g,b,a;
    [r,g,b,a] =  [_rgbInt & 0xff, (_rgbInt & 0xff00)>>8 , (_rgbInt & 0xff0000)>>16, (_rgbInt & 0xff000000)>>24];
    r = min(max(r*_scale,0),255);
    g = min(max(g*_scale,0),255);
    b = min(max(b*_scale,0),255);
    return a << 24 + b<<16 + g<<8 + r;
}

/// <summary>
///    Draws a rectangle on the specified <c>System.Drawing.Graphics</c> object.
/// </summary>
/// <param name="_bmpDC">
///    The <c>System.Drawing.Graphics</c> object to draw on.
/// </param>
/// <param name="_x0">
///    The x coordinate of the upper left corner.
/// </param>
/// <param name="_y0">
///    The y coordinate of the upper left corner.
/// </param>
/// <param name="_w">
///    The width of the rectangle.
/// </param>
/// <param name="_h">
///    The height of the rectangle.
/// </param>
/// <param name="_col">
///    The color to draw with.
/// </param>
/// <param name="_roundCorner">
///    true if rectangle corners must be rounded; otherwise, false.
/// </param>
/// <param name="_vistaLook">
///    true if the rectangle must have a vista look; otherwise, false.
/// </param>
public static void drawLine(System.Drawing.Graphics _bmpDC, int _xStart,int _yStart,int _xEnd,int _yEnd,int _col, boolean _dashed, boolean _vistaLook)
{
    //int                  dX;
    //int                  i;
    //int                  j;
    //int                  w;
    System.Drawing.Color color;
    System.Drawing.Pen   pen;
    InteropPermission    perm;
    int                  col;


    if(_vistaLook)
        col = _col  + real2int(#vistaTrans*255)<<24;
    else
        col = _col;
    color = System.Drawing.Color::FromArgb(col);
    perm = new InteropPermission(InteropKind::ClrInterop);
    perm.assert();

    //BP deviation documented
    pen = new System.Drawing.Pen(color);
    if (_dashed)
    {
        _bmpDC.SmoothingMode = System.Drawing.Drawing2D.SmoothingMode::AntiAlias;
        pen.DashCap = System.Drawing.Drawing2D.DashCap::Round;
        pen.DashStyle = System.Drawing.Drawing2D.DashStyle::DashDotDot;
    }
    _bmpDC.DrawLine(pen,_xStart,_yStart,_xEnd,_yEnd);

    pen.Dispose();

}

/// <summary>
///    Draws a rectangle on the specified <c>System.Drawing.Graphics</c> object.
/// </summary>
/// <param name="_bmpDC">
///    The <c>System.Drawing.Graphics</c> object to draw on.
/// </param>
/// <param name="_x0">
///    The x coordinate of the upper left corner.
/// </param>
/// <param name="_y0">
///    The y coordinate of the upper left corner.
/// </param>
/// <param name="_w">
///    The width of the rectangle.
/// </param>
/// <param name="_h">
///    The height of the rectangle.
/// </param>
/// <param name="_col">
///    The color to draw with.
/// </param>
/// <param name="_roundCorner">
///    true if rectangle corners must be rounded; otherwise, false.
/// </param>
/// <param name="_vistaLook">
///    true if the rectangle must have a vista look; otherwise, false.
/// </param>
public static void drawBmpEdges(System.Drawing.Graphics _bmpDC, int _x0,int _y0,int _w,int _h,int _col, boolean _roundCorner, boolean _vistaLook)
{
    int                  dX;
    int                  i;
    int                  j;
    int                  w;
    System.Drawing.Color color;
    System.Drawing.Pen   pen;
    InteropPermission    perm;
    int                  col;

    w = _w - 1;
    if(_vistaLook)
col = _col  + real2int(#vistaTrans*255)<<24;
    else
col = _col;
    color = System.Drawing.Color::FromArgb(col);
    perm = new InteropPermission(InteropKind::ClrInterop);
    perm.assert();

    //BP deviation documented
    pen = new System.Drawing.Pen(color);
    if(_roundCorner)
dX = 4;

    _bmpDC.DrawLine(pen,_x0+dX,_y0,_x0+w-dX,_y0);
    _bmpDC.DrawLine(pen,_x0+dX,_y0+_h-1,_x0+w-dX,_y0+_h-1);

    _bmpDC.DrawLine(pen,_x0,_y0+dX,_x0,_y0+_h-dX-1);
    _bmpDC.DrawLine(pen,_x0+w,_y0+dX,_x0+w,_y0+_h-dX-1);

    if(!_roundCorner)
return;

    for(i = 0;i<2;i++)
for(j=0;j<2;j++)
    {
        _bmpDC.DrawLine(pen,
                    _x0+2+(i*(w-6))+i,
                    _y0+1+(j*(_h-3)),
                    _x0+3+(i*(w-6))+i,
                    _y0+1+(j*(_h-3)));
    }

    for(i = 0;i<2;i++)
for(j=0;j<2;j++)
    {
        _bmpDC.DrawLine(pen,
                    _x0+1+(i*(w-3))+i,
                    _y0+2+(j*(_h-6)),
                    _x0+1+(i*(w-3))+i,
                    _y0+3+(j*(_h-6)));
    }
    pen.Dispose();

}

/// <summary>
///    Draws a string on the specified <c>System.Drawing.Graphics</c> object.
/// </summary>
/// <param name="_bmpDC">
///    The <c>System.Drawing.Graphics</c> object to draw on.
/// </param>
/// <param name="_x">
///    The x coordinate of the starting point.
/// </param>
/// <param name="_y">
///    The y coordinate of the starting point.
/// </param>
/// <param name="_col">
///    The color to draw width.
/// </param>
/// <param name="_text">
///    The text to draw.
/// </param>
/// <param name="_fontSize">
///    The font size to draw with.
/// </param>
/// <param name="_center">
///    true if the text is centered around the starting point; otherwise, false.
/// </param>
/// <param name="_bold">
///    true if the text is drawn as bold; otherwise, false.
/// </param>
public static int drawText(System.Drawing.Graphics _bmpDC, int _x,int _y, int _col,str _text, int _fontSize, SysChartHorizontalAlignment _xAlign = SysChartHorizontalAlignment::Auto, SysChartVerticalAlignment _yAlign = SysChartVerticalAlignment::Auto, boolean _bold = false, boolean _italic = false, FontName _fontName = 'Verdana', int _maxWidth = 0, boolean _splitToMultipleLines = false)
{
    real i = 0;
    real j = 0;
    System.Drawing.Color		color;
    System.Drawing.Brush		brush;
    System.Drawing.Font			font;
    System.Drawing.StringFormat format;
    System.Drawing.SizeF		mySize;
    System.Drawing.FontStyle    style;
    InteropPermission			perm;
    int                         noOfLines;
    str                         splitText = '';

    perm = new InteropPermission(InteropKind::ClrInterop);
    perm.assert();
    style = System.Drawing.FontStyle::Regular;
    if (_bold)
    {
        style = System.Drawing.FontStyle::Bold;
    }
    //BP deviation documented
    font = new System.Drawing.Font(_fontName /*'Segoe Script'*/,_fontSize,style);

    color = System.Drawing.Color::FromArgb(_col);
    //BP deviation documented
    brush = new System.Drawing.SolidBrush(color);
    //BP deviation documented
    format = new System.Drawing.StringFormat();
    mySize = _bmpDC.MeasureString(_text,font);
    if (_maxWidth && real2int(mySize.get_Width()) > _maxWidth && !_splitToMultipleLines)
    {
        i = _maxWidth / mySize.Width;
        font = new System.Drawing.Font(_fontName /*'Segoe Script'*/,real2int(_fontSize * i),style);
        mySize = _bmpDC.MeasureString(_text,font);
        i = 0;
    }

    if (_maxWidth && real2int(mySize.get_Width()) > _maxWidth && _splitToMultipleLines)
    {
        i = mySize.get_Width() / _maxWidth;
        noOfLines = System.Math::Ceiling(i);
        splitText = TFMGraphicsHelper::splitTextToMultipleLines(_text,noOfLines);

        mySize = _bmpDC.MeasureString(splitText,font);
        i = 0;
    }

    if(_xAlign == SysChartHorizontalAlignment::Center)
    {
        i = mySize.get_Width()/2;//2;
    }
    else if (_xAlign == SysChartHorizontalAlignment::Right)
    {
        i = mySize.get_Width();//2;
    }
    if (_yAlign == SysChartVerticalAlignment::Bottom)
    {
        j = mySize.get_Height();
    }
    else if (_yAlign == SysChartVerticalAlignment::Middle)
    {
        j = mySize.get_Height()/2;
    }
    /*else if (_yAlign == SysChartVerticalAlignment::Top)
    {
        j = 0;// mySize.get_Height();
    }*/


    _bmpDC.set_TextRenderingHint(System.Drawing.Text.TextRenderingHint::AntiAlias);
    _bmpDC.DrawString((splitText ? splitText : _text),font,brush,_x-real2int(i),_y-real2int(j),format);

    brush.Dispose();
    j = mySize.get_Height();
    return j;
}

public static str splitTextToMultipleLines( str _text, int _noOfLines)
{
    str             retText;
    int             strLength = strLen(_text);
    int             lenDelta = strLength / _noOfLines;
    int             prevPos;
    Map             splitPos = new Map (Types::Integer, Types::Integer);
    MapEnumerator   mEnum;
    int i;
    int j;
    for (i = 1; i< _noOfLines; i++)
    {
        for(j = 0; j < lenDelta/2 && !splitPos.exists(i); j++)
        {
            if(subStr(_text,lenDelta*i + j,1) == ' ')
            {
                splitPos.insert(i,lenDelta*i + j);
            }
            else if (subStr(_text,lenDelta*i - j,1) == ' ')
            {
                splitPos.insert(i,lenDelta*i - j);
            }
        }
        if (!splitPos.exists(i))
        {
            splitPos.insert(i,lenDelta*i);
        }
    }
    mEnum = splitPos.getEnumerator();
    prevPos = 0;
    while (mEnum.moveNext())
    {
        retText += subStr(_text,prevPos,mEnum.currentValue()) + TFMConstants::lineBreak();
        prevPos = mEnum.currentValue();
    }
    retText += subStr(_text,prevPos,10000);
    return retText;
}

public static container measureText(System.Drawing.Graphics _bmpDC, str _text, int _fontSize, boolean _bold = false, boolean _italic = false, FontName _fontName = 'Verdana')
{
    real i = 0;
    real j = 0;


    System.Drawing.Font			font;
    System.Drawing.SizeF		mySize;
    System.Drawing.FontStyle    style;
    InteropPermission			perm;
    ;
    perm = new InteropPermission(InteropKind::ClrInterop);
    perm.assert();
    style = System.Drawing.FontStyle::Regular;
    if (_bold)
    {
        style = System.Drawing.FontStyle::Bold;
    }
    //BP deviation documented
    font = new System.Drawing.Font(_fontName /*'Segoe Script'*/,_fontSize,style);

    mySize = _bmpDC.MeasureString(_text,font);
    i = mySize.get_Width();
    j = mySize.get_Height();
    return [i,j];
}

/// <summary>
///    Draws a rectangle gradient on the specified <c>System.Drawing.Graphics</c> object.
/// </summary>
/// <param name="_bmpDC">
///    The <c>System.Drawing.Graphics</c> object to draw on.
/// </param>
/// <param name="_x0">
///    The x coordinate of the upper left corner of the rectangle.
/// </param>
/// <param name="_y0">
///    The y coordinate of the upper left corner of the rectangle.
/// </param>
/// <param name="_w">
///    The width of the rectangle.
/// </param>
/// <param name="_h">
///    The height of the rectangle
/// </param>
/// <param name="_uCol">
///    The upper color of the gradient.
/// </param>
/// <param name="_lCol">
///    The lower color of the gradient.
/// </param>
/// <param name="_roundCorner">
///    true if the rectangle must be drawn with rounded corners; otherwise, false.
/// </param>
/// <param name="_vistaLook">
///    true if the gradient must have a vista look; otherwise, false.
/// </param>
public static void drawGradient(System.Drawing.Graphics _bmpDC, int _x0,int _y0,int _w,int _h,int _uCol,int _lCol, boolean _roundCorner, boolean _vistaLook)
{
    int                  i;
    int                  myWidth;
    int                  col;
    int                  ur,ug,ub,lr,lg,lb,r,g,b,or,og,ob;
    real                 w;
    int                  dX;
    //int                  resW = 0;
    //int                  resH = 0;
    //int                  xMargin = 3;
    System.Drawing.Pen   pen;
    System.Drawing.Color color;
    InteropPermission    perm;

    int makeVista(int _col, int _i, int _iMax)
    {
        return real2int((255-((255-_col)*((_i/_iMax)*0.4+0.4))));
    }
    container rgbInt2Con(int _rgbInt)
    {
        return [_rgbInt & 0xff, (_rgbInt & 0xff00)>>8 , (_rgbInt & 0xff0000)>>16];
    }
    int rgb2int(RGBint _r, RGBint _g, RGBint _b)
    {
        return _r  + _g<<8 + _b<<16;
    }

    perm = new InteropPermission(InteropKind::ClrInterop);
    perm.assert();

    [ur,ug,ub] = rgBint2Con(_uCol);
    [lr,lg,lb] = rgBint2Con(_lCol);

    dX = 0;

    myWidth = _w-1;


    for(i = _y0;i<_y0+_h;i++)
    {
        if (_h != 1)
        {
            w = (i-_y0)/(_h-1);
            if(_vistaLook)
        w = w*w;

            or =w*lr+(1-w)*ur;
            og = w*lg+(1-w)*ug;
            ob = w*lb+(1-w)*ub;
            r = or;
            g = og;
            b = ob;
            if(_vistaLook && (i-_y0 <(_h/2)))
            {
                r = makeVista(r,i-_y0,_h/2);
                g = makeVista(g,i-_y0,_h/2);
                b = makeVista(b,i-_y0,_h/2);
            }
            col = rgb2int(b,g,r);

            col += 255<<24;

            if(_roundCorner)
            {
                dX = ((i <= _y0+3) || (i >= (_y0+_h-4)))?1:0;
                dX = ((i == _y0) || (i == (_y0+_h-1)))?4:dX;
                dX = ((i == _y0+1) || (i == (_y0+_h-2)))?2:dX;
            }
            color = System.Drawing.Color::FromArgb(col);
            //BP deviation documented
            pen = new System.Drawing.Pen(color);
            _bmpDC.DrawLine(pen,_x0+dX,i,_x0+myWidth-dX,i);

            pen.Dispose();
        }
    }
}

/// <summary>
/// Switches an RGB integer to a BGR integer.
/// </summary>
/// <param name="_rgbInt">
/// The RGB integer to switch.
/// </param>
/// <returns>
/// The resulting BGR value.
/// </returns>
public static int switchTOBGR(int _rgbInt)
{
    int r,g,b,a;
    [r,g,b,a] =  [_rgbInt & 0xff, (_rgbInt & 0xff00)>>8 , (_rgbInt & 0xff0000)>>16, (_rgbInt & 0xff000000)>>24];
    return a << 24 + r<<16 + g<<8 + b;
}

