public static str getImageURL(System.Drawing.Bitmap _bmp)
{

    System.IO.MemoryStream ms = new System.IO.MemoryStream();
    System.Drawing.Imaging.ImageFormat imgFormat = System.Drawing.Imaging.ImageFormat::Png;

    _bmp.Save(ms, imgFormat);

    FileUploadTemporaryStorageStrategy fileUploadStrategy = new FileUploadTemporaryStorageStrategy();

    FileUploadTemporaryStorageResult fileUploadResult = fileUploadStrategy.uploadFile(ms, 'tf');
    if(fileUploadResult && fileUploadResult.getUploadStatus())
    {
        //put process file code here.
    }
    else
    {
        throw error("@TFM:Unabletoloadfile");
    }


    return fileUploadResult.getDownloadUrl(false);


}

public Static System.Drawing.Bitmap initBaseBmp(int _width, int _height, boolean _stripes = true)
{
    InteropPermission			perm = new InteropPermission(InteropKind::ClrInterop);
    System.Drawing.Pen			pen;
    System.Drawing.Pen			penBig;
    System.Drawing.Brush		brush;
    System.Drawing.Color		color;
    System.Drawing.Graphics		bmpDC;
    int							i;
    System.Drawing.Bitmap		bmpBase;
    System.Drawing.Image		holeImage = TFMImageHelper::base64ToImage(TFMImageHelper::resource2Base64(resourceStr(TFMPaperHole)));
    System.Drawing.Rectangle	rect;
    perm.assert();
    //BP deviation documented
    bmpBase = new System.Drawing.Bitmap(_width,_height);
    bmpDC = System.Drawing.Graphics::FromImage(bmpBase);
    color = System.Drawing.Color::FromArgb(255 +255<<8 +255 <<16 + 255<<24);

    //BP deviation documented
    brush = new System.Drawing.SolidBrush(color);

    bmpDC.FillRectangle(brush,0,0,_width,_height);
    brush.Dispose();
    if (!_stripes)
    {
        return bmpBase;
    }
    //bmpDC.set_SmoothingMode(System.Drawing.Drawing2D.SmoothingMode::AntiAlias);
    color = System.Drawing.Color::FromArgb(255 +164<<8 +164 <<16 + 64<<24);
    //BP deviation documented
    Pen = new System.Drawing.Pen(color,1);
    PenBig = new System.Drawing.Pen(color,2);
    for (i = 1; i < _height/20;i++)
    {
        bmpDC.DrawLine(pen,0,i*20,_width,i*20);
    }
    for (i = 1; i < _width/20;i++)
    {

        bmpDC.DrawLine(i == 5 ? PenBig : pen,i*20,0,i*20,_height);
    }

    pen.Dispose();

    for (i = 0; i < 4; i++)
    {
        rect = new System.Drawing.Rectangle(30,50 + i* 400,25,25);
        bmpDC.DrawImage(holeImage,rect);
    }

    return bmpBase;
}

/// <summary>
///    Draws a gradient circle on the specified <c>System.Drawing.Graphics</c> object.
/// </summary>
/// <param name="_bmpDC">
///    The <c>System.Drawing.Graphics</c> object to draw on.
/// </param>
/// <param name="_x0">
///    The x coordinate of the circle center.
/// </param>
/// <param name="_y0">
///    The y coordinate of the circle center.
/// </param>
/// <param name="_radius">
///    The radius of the circle.
/// </param>
/// <param name="_upColor">
///    The upper color of the gradient.
/// </param>
/// <param name="_loColor">
///    The lower color of the gradient.
/// </param>
/// <param name="_noVista">
///    true if the gradient must not have a vista look; otherwise, false.
/// </param>
public static void drawGradientCircle(System.Drawing.Graphics _bmpDC, int _x0, int _y0, real _radius, int _upColor, int _loColor, boolean _noVista = false)
{
    int yMin, yMax;
    int y;
    int xMin, xMax;
    int col;
    int ur,ug,ub,lr,lg,lb,r,g,b;
    real    w;
    int     resW = 0;
    int     resH = 0;
    InteropPermission       perm;
    System.Drawing.Pen  pen;
    System.Drawing.Color    color;

    perm = new InteropPermission(InteropKind::ClrInterop);
    perm.assert();

    [ur,ug,ub] = TFMGraphicsHelper::rgBint2Con(_upColor);
    [lr,lg,lb] = TFMGraphicsHelper::rgBint2Con(_loColor);

    yMin = _y0 - real2int(_radius);
    yMax = _y0 + real2int(_radius);

    for(y = yMin;y<=yMax;y++)

    {
        //Color calculation begin
        w = (y-yMin)/(2*_radius-1);
        //Exponential Gradient to gain vista-look
        w = w*w;

        r =w*lr+(1-w)*ur;
        g = w*lg+(1-w)*ug;
        b = w*lb+(1-w)*ub;

        if(y-yMin <_radius && !_noVista)

        {
            r = TFMGraphicsHelper::makeVista(r,y-yMin,real2int(_radius));
            g = TFMGraphicsHelper::makeVista(g,y-yMin,real2int(_radius));
            b = TFMGraphicsHelper::makeVista(b,y-yMin,real2int(_radius));

        }
        col = TFMGraphicsHelper::rgb2int(b,g,r);

        //Set alpha
        col += 255<<24;
        //Color Calculation end

        color = System.Drawing.Color::FromArgb(col);
        //BP deviation documented
        pen = new System.Drawing.Pen(color);

        [xMax,xMin] = TFMGraphicsHelper::findIntersections(y, _x0, _y0, _radius);
        _bmpDC.DrawLine(pen,xMin,y,xMax,y);

        pen.Dispose();

    }



}

public static int makeVista(int _col, int _i, int _iMax)

{
    return real2int(255-((255-_col)*((_i/_iMax)*0.4+0.4)));

}

public static container rgbInt2Con(int _rgbInt)
{
    return [_rgbInt & 0xff, (_rgbInt & 0xff00)>>8 , (_rgbInt & 0xff0000)>>16];

}

public static int rgb2int(RGBint _r, RGBint _g, RGBint _b)

{
    return _r  + _g<<8 + _b<<16;

}

public static container findIntersections(int _y, int _cX, int _cY, real _rad)

{
    real radTwo = _rad*_rad;
    real yTwo   = (_y-_cY)*(_y-_cY);
    real ret;
    ;
    ret = 0;
    if (radTwo >= yTwo)
                    ret = sqrt(radTwo - yTwo) + _cX;

    return [ret,_cX-(ret-_cX)];

}

/// <summary>
///    Draws a specular overlay on the specified <c>System.Drawing.Graphics</c> object.
/// </summary>
/// <param name="_bmpDC">
///    The <c>System.Drawing.Graphics</c> object to draw on.
/// </param>
/// <param name="_x0">
///    The x coordinate of the starting point
/// </param>
/// <param name="_y0">
///    The y coordinate of the starting point.
/// </param>
/// <param name="_w">
///    The width of the specular overlay.
/// </param>
/// <param name="_h">
///    The height of the specular overlay.
/// </param>
/// <param name="_roundCorner">
///    true if corners must be rounded; otherwise, false.
/// </param>
public static void drawSpecularOverlay(System.Drawing.Graphics _bmpDC, int _x0,int _y0,int _w,int _h, boolean _roundCorner)

{
    int                  i;
    int                  myWidth;
    int                  col;
    int                  dX;
    int                  resW = 0;
    int                  resH = 0;
    int                  xMargin = 3;
    System.Drawing.Pen   pen;
    System.Drawing.Color color;
    InteropPermission    perm;

    perm = new InteropPermission(InteropKind::ClrInterop);
    perm.assert();

    myWidth = _w-1;

    for(i = _y0;i<_y0+_h;i++)

    {
        col = 0;
        if((i-_y0 <(_h/2)))

        {
            col = TFMGraphicsHelper::specColor(i-_y0,_h/2);

        }

        if(_roundCorner)

        {
            dX = ((i <= _y0+3) || (i >= (_y0+_h-4)))?1:0;
            dX = ((i == _y0) || (i == (_y0+_h-1)))?4:dX;
            dX = ((i == _y0+1) || (i == (_y0+_h-2)))?2:dX;

        }
        color = System.Drawing.Color::FromArgb(col);
        //BP deviation documented
        pen = new System.Drawing.Pen(color);

        _bmpDC.DrawLine(pen,_x0+dX,i,_x0+myWidth-dX,i);

        pen.Dispose();

    }

}

public static int specColor(int _i,int _iMax)

{
    return 255<<16+255<<8+255+real2int(255*((_i/_iMax)*0.2+0.2))<<24;
}

